package com.travessia.segura.road

object RoadText {
    fun get(language: String, key: String): String {
        val texts = when (key) {
            "yes_word" -> listOf("sim", "yes", "sí")
            "question_interrupted" -> listOf("Pergunta interrompida. Use os botões Sim ou Não.", "Question interrupted. Use the Yes or No buttons.", "Pregunta interrumpida. Use los botones Sí o No.")
            "retry_speech" -> listOf("Não entendi. Após o sinal, repita apenas sim ou não.", "Not understood. After the tone, say only yes or no.", "No entendí. Después de la señal, diga solo sí o no.")
            "offline_unavailable" -> listOf("Reconhecimento de voz offline indisponível. Use os botões sim ou não.", "Offline speech recognition unavailable. Use the yes or no buttons.", "Reconocimiento de voz sin conexión no disponible. Use los botones sí o no.")
            "microphone_unavailable" -> listOf("Permita o microfone para responder por voz. Os botões sim e não estão disponíveis.", "Allow microphone access to answer by voice. Yes and no buttons are available.", "Permita el micrófono para responder por voz. Los botones sí y no están disponibles.")
            "AWAITING_CONFIRMATION" -> listOf("Possível rua à frente. Não consegui confirmar uma faixa de pedestres. Deseja verificar o trânsito? Após o sinal, diga sim ou não.", "Possible road ahead. I could not confirm a crosswalk. Would you like to check traffic? After the tone, say yes or no.", "Posible calle adelante. No pude confirmar un cruce peatonal. ¿Desea verificar el tráfico? Después de la señal, diga sí o no.")
            "approaching_left" -> listOf("Atenção! Veículo se aproximando pela esquerda. Aguarde.", "Warning! Vehicle approaching from the left. Wait.", "¡Atención! Vehículo acercándose por la izquierda. Espere.")
            "approaching_right" -> listOf("Atenção! Veículo se aproximando pela direita. Aguarde.", "Warning! Vehicle approaching from the right. Wait.", "¡Atención! Vehículo acercándose por la derecha. Espere.")
            "crosswalk_occupied" -> listOf("Atenção! Veículo na faixa de pedestres. Aguarde.", "Warning! Vehicle on the crosswalk. Wait.", "¡Atención! Vehículo en el cruce peatonal. Espere.")
            "obstacle_ahead" -> listOf("Atenção! Obstáculo à frente.", "Warning! Obstacle ahead.", "¡Atención! Obstáculo adelante.")
            "traffic_uncertain" -> listOf("Não consegui confirmar o movimento dos veículos. Vamos verificar novamente.", "I could not confirm vehicle movement. Let's check again.", "No pude confirmar el movimiento de los vehículos. Verifiquemos de nuevo.")
            "traffic_potential" -> listOf("Atenção! Veículo na trajetória observada. Movimento incerto. Aguarde.", "Warning! Vehicle in the observed path. Movement uncertain. Wait.", "¡Atención! Vehículo en la trayectoria observada. Movimiento incierto. Espere.")
            "verify_analyzing" -> listOf("Verificando o trânsito. Mantenha a câmera nesta direção.", "Checking traffic. Keep the camera pointed this way.", "Verificando el tráfico. Mantenga la cámara en esta dirección.")
            "verify_crosswalk" -> listOf("Faixa de pedestres identificada. Permaneça na calçada. Vamos verificar o trânsito.", "Crosswalk identified. Remain on the sidewalk. Let's check traffic.", "Cruce peatonal identificado. Permanezca en la acera. Verifiquemos el tráfico.")
            "verify_hand" -> listOf("Se não houver sinal de pedestres aplicável, levante uma das mãos para sinalizar sua intenção. Permaneça na calçada.", "If there is no applicable pedestrian signal, raise one hand to signal your intention. Stay on the sidewalk.", "Si no hay una señal peatonal aplicable, levante una mano para indicar su intención. Permanezca en la acera.")
            "verify_right" -> listOf("Vire a câmera para a direita e confirme no botão.", "Turn the camera to the right and confirm with the button.", "Gire la cámara a la derecha y confirme con el botón.")
            "verify_left" -> listOf("Verificação concluída. Agora vire para a esquerda e confirme no botão.", "Check completed. Now turn to the left and confirm with the button.", "Verificación completada. Ahora gire a la izquierda y confirme con el botón.")
            "verify_front" -> listOf("Verificação concluída. Volte a câmera para a frente e confirme no botão.", "Check completed. Point the camera forward again and confirm with the button.", "Verificación completada. Vuelva a apuntar la cámara hacia adelante y confirme con el botón.")
            "verify_favorable" -> listOf("Verificação concluída. Não identifiquei veículos se aproximando. Condições favoráveis para a travessia neste momento. A câmera não garante que a via esteja livre.", "Check completed. I did not identify approaching vehicles. Conditions appear favorable for crossing at this moment. The camera cannot guarantee a clear road.", "Verificación completada. No identifiqué vehículos acercándose. Condiciones favorables para cruzar en este momento. La cámara no garantiza que la vía esté libre.")
            "verify_inconclusive" -> listOf("Não consegui confirmar as condições do trânsito. Vamos verificar novamente. Reposicione a câmera.", "I could not confirm traffic conditions. Let's check again. Reposition the camera.", "No pude confirmar las condiciones del tráfico. Verifiquemos de nuevo. Reposicione la cámara.")
            "verify_direction_unavailable" -> listOf("Não consigo comprovar a direção e a cobertura da câmera. A verificação da travessia está inconclusiva. Os alertas continuam ativos.", "I cannot verify the camera direction and coverage. The crossing check is inconclusive. Alerts remain active.", "No puedo comprobar la dirección y la cobertura de la cámara. La verificación del cruce no es concluyente. Las alertas siguen activas.")
            "verify_no_crosswalk" -> listOf("Não consigo avaliar se esta travessia sem faixa é apropriada. Não posso confirmar condições favoráveis aqui.", "I cannot assess whether this crossing without a crosswalk is appropriate. I cannot confirm favorable conditions here.", "No puedo evaluar si este cruce sin paso peatonal es apropiado. No puedo confirmar condiciones favorables aquí.")
            "verify_danger" -> listOf("Atenção! Não foi possível manter uma condição favorável. Aguarde.", "Warning! Favorable conditions could not be maintained. Wait.", "¡Atención! No fue posible mantener condiciones favorables. Espere.")
            "confirm_right" -> listOf("Câmera à direita: confirmar", "Camera to the right: confirm", "Cámara a la derecha: confirmar")
            "confirm_left" -> listOf("Câmera à esquerda: confirmar", "Camera to the left: confirm", "Cámara a la izquierda: confirmar")
            "confirm_front" -> listOf("Câmera à frente: confirmar", "Camera forward: confirm", "Cámara al frente: confirmar")
            "capture_width" -> listOf("Largura da captura CameraX (pixels)", "CameraX capture width (pixels)", "Ancho de captura CameraX (píxeles)")
            "video_error" -> listOf("Não consigo analisar a imagem. Verifique a câmera.", "I cannot analyze the image. Check the camera.", "No puedo analizar la imagen. Revise la cámara.")
            "listening" -> listOf("Microfone aberto. Diga sim ou não.", "Microphone ready. Say yes or no.", "Micrófono abierto. Diga sí o no.")
            "speech_error" -> listOf("Não consegui reconhecer a resposta. Use o botão Sim ou Não.", "Could not recognize the answer. Use Yes or No.", "No pude reconocer la respuesta. Use Sí o No.")
            "STARTING_ANALYSIS" -> listOf("Sim reconhecido. Preparando análise de veículos e semáforos.", "Yes recognized. Preparing vehicle and traffic light analysis.", "Sí reconocido. Preparando análisis de vehículos y semáforos.")
            "yes" -> listOf("Sim, analisar", "Yes, analyze", "Sí, analizar")
            "no" -> listOf("Não", "No", "No")
            "declined" -> listOf("Análise não iniciada. Continuando o monitoramento.", "Analysis not started. Monitoring continues.", "Análisis no iniciado. Continúa el monitoreo.")
            "unheard" -> listOf("Não ouvi um sim ou não claro. Análise não iniciada.", "No clear yes or no heard. Analysis not started.", "No escuché un sí o no claro. Análisis no iniciado.")
            "consent_yes" -> listOf("Sim reconhecido. Preparando análise do ambiente.", "Yes recognized. Preparing scene analysis.", "Sí reconocido. Preparando análisis del entorno.")
            "license" -> listOf("Licença e créditos FFNet", "FFNet license and credits", "Licencia y créditos FFNet")
            "setting" -> listOf("Detecção automática de ruas", "Automatic road detection", "Detección automática de calles")
            "subtitle" -> listOf("Monitoramento visual experimental local. Não autoriza travessias.", "Experimental offline visual monitoring. Does not authorize crossing.", "Monitoreo visual experimental local. No autoriza cruzar.")
            "debug" -> listOf("Modo desenvolvedor: segmentação e métricas", "Developer mode: segmentation and metrics", "Modo desarrollador: segmentación y métricas")
            "seg_fps" -> listOf("Frequência FFNet (FPS)", "FFNet frequency (FPS)", "Frecuencia FFNet (FPS)")
            "yolo_fps" -> listOf("Limite YOLO (FPS)", "YOLO limit (FPS)", "Límite YOLO (FPS)")
            "confirm" -> listOf("Confirmação visual (ms)", "Visual confirmation (ms)", "Confirmación visual (ms)")
            "hold" -> listOf("Histerese de saída (ms)", "Exit hysteresis (ms)", "Histéresis de salida (ms)")
            "cooldown" -> listOf("Intervalo entre ativações (ms)", "Activation cooldown (ms)", "Intervalo de activación (ms)")
            "MONITORING" -> listOf("Monitoramento automático ativo", "Automatic monitoring active", "Monitoreo automático activo")
            "POSSIBLE_CROSSING" -> listOf("Possível travessia identificada", "Possible crossing identified", "Posible cruce identificado")
            "ACTIVE_ANALYSIS" -> listOf("Análise de veículos e semáforos ativa.", "Vehicle and traffic light analysis active.", "Análisis de vehículos y semáforos activo.")
            "ERROR" -> listOf("Erro no monitoramento visual. Use a análise manual.", "Visual monitoring error. Use manual analysis.", "Error de monitoreo visual. Use el análisis manual.")
            "road" -> listOf("Rua detectada", "Road detected", "Calle detectada")
            "sidewalk" -> listOf("Calçada detectada", "Sidewalk detected", "Acera detectada")
            "INCONCLUSIVE" -> listOf("A rua não foi identificada com clareza nesta imagem.", "Road not clearly identified in this image.", "La calle no se identificó claramente en esta imagen.")
            "stale_frame" -> listOf("Imagem atrasada. Aguardando uma imagem atual.", "Delayed image. Waiting for a current frame.", "Imagen atrasada. Esperando una imagen actual.")
            "context_only" -> listOf("Segmentação da rua indisponível neste quadro. Análise de veículos ativa.", "Road segmentation unavailable for this frame. Vehicle analysis active.", "Segmentación de calle no disponible en este cuadro. Análisis de vehículos activo.")
            else -> listOf("Não foi possível confirmar as condições da via.", "Could not confirm road conditions.", "No fue posible confirmar las condiciones de la vía.")
        }
        return texts[when (language) { "en" -> 1; "es" -> 2; else -> 0 }]
    }
}
